<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {get} from 'svelte/store';
 import {user} from '$lib/stores';
 import {parseNativeAuthority,projectNativeDirectory} from '$lib/utils/company-authority';
 import {CompanyClient} from '$lib/utils/company-workspace';
 export let companyId:string;
 let client:CompanyClient,people:any[]=[],roles:any[]=[],permissions:any[]=[],caps:string[]=[],error='',notice='',alive=true,busy=false,loading=true;
 let name='',kind='person',grants:string[]=[],subject='',customRole='',builtin='member';
 async function call(path:string,method='GET',body?:unknown){return client.request(path,method,body,undefined,true);}
 async function load(){loading=true;try{const actor=get(user)?.id||'';const [raw,d,r,p]=await Promise.all([call('/capabilities'),call('/directory'),call('/roles'),call('/permissions')]);if(!alive||actor!==get(user)?.id)return;const scope=parseNativeAuthority(raw,companyId,actor);if(!Array.isArray(r)||!Array.isArray(p.permissions))throw Error('Company administration contract is unavailable.');people=projectNativeDirectory(d,scope);caps=scope.capabilities;roles=r.filter((x:any)=>x.active);permissions=p.permissions.filter((x:any)=>x?.delegable);error='';}catch(e){if(alive){people=[];roles=[];caps=[];error=(e as Error).message;}}finally{if(alive)loading=false;}}
 async function change(action:()=>Promise<any>,text:string){if(busy)return;busy=true;try{await action();if(alive){notice=text;await load();}}catch(e){if(alive)error=(e as Error).message;}finally{if(alive)busy=false;}}
 onMount(()=>{client=new CompanyClient(companyId,()=>localStorage.token||'');void load();});onDestroy(()=>{alive=false;client?.close();});
</script>
<section aria-label="Company roles"><h2>People and bot roles</h2><p>Human and bot permissions are managed separately. Shared resources keep their own access rules.</p>
 {#if loading}<p role="status">Checking company permissions…</p>{:else}{#if caps.includes('roles.manage')}<form on:submit|preventDefault={()=>change(()=>call('/roles','POST',{name,kind,grants}),'Role created.')}><h3>Create a role</h3><label>Role name<input bind:value={name} maxlength="100" required/></label><label>Applies to<select bind:value={kind}><option value="person">People</option><option value="bot">AI agent bots</option></select></label><fieldset><legend>Permissions</legend>{#each permissions as p}<label class="grant"><input type="checkbox" bind:group={grants} value={p.name}/>{p.name.replaceAll('.',' · ')}</label>{/each}</fieldset><button class="sd-button" disabled={busy||!name.trim()}>Create role</button></form>
 <form on:submit|preventDefault={()=>change(()=>call('/roles/'+encodeURIComponent(customRole)+'/members/'+encodeURIComponent(subject),'PUT'),'Role assigned.')}><h3>Assign a custom role</h3><label>Person or bot<select bind:value={subject}><option value="">Choose a member</option>{#each people as p}<option value={p.id}>{p.name} · {p.kind==='bot'?'AI agent':'Person'}</option>{/each}</select></label><label>Role<select bind:value={customRole}><option value="">Choose a role</option>{#each roles.filter(r=>r.kind===people.find(p=>p.id===subject)?.kind) as r}<option value={r.id}>{r.name}</option>{/each}</select></label><div class="actions"><button class="sd-button" disabled={busy||!subject||!customRole}>Assign role</button><button type="button" class="sd-button" disabled={busy||!subject||!customRole} on:click={()=>change(()=>call('/roles/'+encodeURIComponent(customRole)+'/members/'+encodeURIComponent(subject),'DELETE'),'Role assignment revoked.')}>Revoke assignment</button></div></form>
 <form on:submit|preventDefault={()=>change(()=>call('/members/'+encodeURIComponent(subject)+'/role','PUT',{role:builtin}),'Company role updated.')}><h3>Company administrator role</h3><label>Person<select bind:value={subject}><option value="">Choose a person</option>{#each people.filter(p=>p.kind==='person') as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label>Role<select bind:value={builtin}><option value="member">Member</option><option value="admin">Administrator</option>{#if caps.includes('owners.manage')}<option value="owner">Owner</option>{/if}</select></label><button class="sd-button" disabled={busy||!subject||people.find(p=>p.id===subject)?.kind!=='person'}>Update role</button></form>
 {:else}<p>Company administrators manage roles. You can view the roles available to this company.</p>{/if}
 {#if caps.includes('members.remove')}<form on:submit|preventDefault={()=>change(()=>call('/members/'+encodeURIComponent(subject),'DELETE'),'Company membership removed.')}><h3>Remove a member</h3><label>Member<select aria-label="Member to remove" bind:value={subject}><option value="">Choose a member</option>{#each people as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button class="sd-button" disabled={busy||!subject}>Remove company member</button></form>{/if}
 <div>{#each roles as r}<article><strong>{r.name}</strong><small>{r.kind==='bot'?'AI agent bots':'People'} · {r.grants.length} permissions</small>{#if caps.includes('roles.manage')}<button class="sd-button" disabled={busy} on:click={()=>change(()=>call('/roles/'+encodeURIComponent(r.id),'DELETE'),'Role revoked.')}>Revoke role</button>{/if}</article>{/each}</div>
 {/if}{#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
</section>
<style>section{min-width:0}h2{font-size:19px;font-weight:650}h3{font-size:14px;font-weight:650;margin:14px 0 8px}p,small,legend{font-size:12px;color:var(--sd-muted)}form{border-bottom:1px solid var(--sd-line);padding:8px 0 18px}label{display:block;font-size:13px;margin:8px 0}input:not([type=checkbox]),select{display:block;padding:8px;width:100%;background:var(--sd-card);color:inherit;border:1px solid var(--sd-line);border-radius:8px}.grant{display:inline-flex;gap:6px;align-items:center;margin-right:14px}article{padding:12px 0;border-bottom:1px solid var(--sd-line);display:flex;gap:12px;align-items:center;flex-wrap:wrap}article strong{font-size:14px}.actions{display:flex;gap:8px;flex-wrap:wrap}</style>
